import React from 'react';
import { useApp } from '../context/AppContext';
import { PRESET_COLORS } from '../constants';
import { Trash2, Copy, Maximize, Layers, ArrowUpFromLine } from 'lucide-react';
import { IPoint } from '../types';

// Helper to determine local bounding box from points
const getRawDimensions = (points: IPoint[]) => {
  if (points.length === 0) return { width: 0, depth: 0 };
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
  points.forEach(p => {
    minX = Math.min(minX, p.x);
    maxX = Math.max(maxX, p.x);
    minZ = Math.min(minZ, p.z);
    maxZ = Math.max(maxZ, p.z);
  });
  return { 
    width: maxX - minX || 0.1, 
    depth: maxZ - minZ || 0.1 
  };
};

const PropertiesPanel: React.FC = () => {
  const { selectedIds, shapes, updateShape, updateShapes, removeSelected, copySelected, formatValue, unit } = useApp();

  if (selectedIds.length === 0) {
    return null;
  }

  // --- Multi Selection View ---
  if (selectedIds.length > 1) {
      return (
        <div className="absolute top-20 right-4 w-60 bg-slate-800/90 backdrop-blur-sm rounded-xl border border-slate-700 shadow-xl z-30 flex flex-col overflow-hidden">
            <div className="p-3 border-b border-slate-700 bg-slate-900/50 flex justify-between items-center sticky top-0 z-20">
                <h3 className="text-white font-semibold text-xs flex items-center gap-2">
                    <Layers size={14} className="text-blue-500"/>
                    <span>已選取 {selectedIds.length} 個物件</span>
                </h3>
                <div className="flex gap-1">
                    <button 
                        onClick={copySelected}
                        className="text-indigo-400 hover:text-indigo-300 p-1 hover:bg-indigo-500/10 rounded transition-colors"
                        title="複製選取物件"
                    >
                        <Copy size={14} />
                    </button>
                    <button 
                        onClick={removeSelected}
                        className="text-red-400 hover:text-red-300 p-1 hover:bg-red-500/10 rounded transition-colors"
                        title="刪除選取物件"
                    >
                        <Trash2 size={14} />
                    </button>
                </div>
            </div>
            <div className="p-3 space-y-4">
                 {/* Batch Color Picker */}
                <div className="space-y-1.5">
                    <label className="text-[10px] text-slate-400 font-medium uppercase tracking-wider">批次修改顏色</label>
                    <div className="grid grid-cols-4 gap-1.5">
                        {PRESET_COLORS.map(color => (
                        <button
                            key={color}
                            onClick={() => {
                                const updates = selectedIds.map(id => ({ id, changes: { color }}));
                                updateShapes(updates);
                            }}
                            className={`w-full aspect-square rounded-md border-2 border-transparent hover:scale-105 transition-transform`}
                            style={{ backgroundColor: color }}
                        />
                        ))}
                    </div>
                </div>
            </div>
        </div>
      );
  }

  // --- Single Selection View ---
  const selectedShape = shapes.find(s => s.id === selectedIds[0]);
  if (!selectedShape) return null;

  // Calculate current real-world dimensions
  const rawDims = getRawDimensions(selectedShape.points);
  const currentWidth = rawDims.width * selectedShape.scale[0];
  const currentDepth = rawDims.depth * selectedShape.scale[2];

  // Simple numeric updates (Standard center-based scaling for manual input)
  const handleDimensionChange = (newVal: number, type: 'width' | 'depth') => {
    if (isNaN(newVal) || newVal <= 0) return;
    const baseSize = type === 'width' ? rawDims.width : rawDims.depth;
    if (baseSize < 0.001) return;
    const newScaleVal = newVal / baseSize;

    const newScale = [...selectedShape.scale] as [number, number, number];
    if (type === 'width') newScale[0] = newScaleVal;
    if (type === 'depth') newScale[2] = newScaleVal;

    updateShape(selectedShape.id, { scale: newScale });
  };

