                     <input 
                        type="number" 
                        step={0.1}
                        value={selectedShape.fontSize || 0.5}
                        onChange={(e) => updateShape(selectedShape.id, { fontSize: parseFloat(e.target.value) })}
                        className="w-16 bg-slate-900 border border-slate-600 rounded px-1.5 py-0.5 text-white text-xs font-mono focus:border-blue-500 outline-none text-right"
                     />
                 </div>
            </div>
        )}

        {/* --- Dimensions Section --- */}
        {selectedShape.type !== 'text' && selectedShape.type !== 'line' && (
