                newRot[1] = parseFloat(e.target.value);
                updateShape(selectedShape.id, { rotation: newRot });
            }}
            className="w-full h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
          />
        </div>

        {/* Color Picker */}
        <div className="space-y-1.5 pt-1">
          <label className="text-[10px] text-slate-400 font-medium uppercase tracking-wider">材質顏色</label>
          <div className="grid grid-cols-5 gap-1.5">
            {PRESET_COLORS.map(color => (
              <button
                key={color}
                onClick={() => updateShape(selectedShape.id, { color })}
                className={`w-full aspect-square rounded border transition-transform hover:scale-110 ${selectedShape.color === color ? 'border-white ring-1 ring-blue-500/50' : 'border-transparent'}`}
                style={{ backgroundColor: color }}
              />
            ))}
            <div className="relative w-full aspect-square rounded overflow-hidden bg-gradient-to-br from-white to-black border border-slate-600 hover:scale-110 transition-transform">
                <input 
                    type="color" 
                    className="absolute inset-0 w-[150%] h-[150%] -top-1/4 -left-1/4 cursor-pointer opacity-0" 
                    value={selectedShape.color}
                    onChange={(e) => updateShape(selectedShape.id, { color: e.target.value })}
                />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

