                <label className="text-[10px] text-slate-400 font-medium uppercase tracking-wider">本體高度</label>
                <div className="flex items-center gap-1">
                    <input 
                        type="number" 
                        step={unit === 'm' ? 0.1 : 5}
                        value={getUnitVal(selectedShape.height)}
                        onChange={(e) => updateShape(selectedShape.id, { height: setUnitVal(parseFloat(e.target.value)) })}
                        className="w-14 bg-slate-900 border border-slate-600 rounded px-1.5 py-0.5 text-white text-xs font-mono focus:border-green-500 outline-none text-right"
                    />
                    <span className="text-[9px] text-slate-500">{unit === 'cm' ? 'cm' : 'm'}</span>
                </div>
            </div>
            <input
                type="range"
                min="0.05"
                max="5"
                step="0.05"
                value={selectedShape.height}
                onChange={(e) => updateShape(selectedShape.id, { height: parseFloat(e.target.value) })}
                className="w-full h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-slate-400"
            />
            </div>
        )}

        {/* Rotation Y */}
        <div className="space-y-2 pt-2 border-t border-slate-700/50">
          <div className="flex justify-between items-center">
             <label className="text-[10px] text-slate-400 font-medium uppercase tracking-wider">旋轉 (Y軸)</label>
             <span className="text-blue-400 font-mono text-xs">{((selectedShape.rotation[1] * 180) / Math.PI).toFixed(0)}°</span>
          </div>
          <input
            type="range"
            min="0"
            max={Math.PI * 2}
            step="0.1"
            value={selectedShape.rotation[1]}
            onChange={(e) => {
                const newRot = [...selectedShape.rotation] as [number, number, number];
                newRot[1] = parseFloat(e.target.value);
                updateShape(selectedShape.id, { rotation: newRot });
            }}
            className="w-full h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
          />
        </div>

        {/* Rotation X (For Text Only) */}
        {selectedShape.type === 'text' && (
            <div className="space-y-2 pt-2 border-t border-slate-700/50">
              <div className="flex justify-between items-center">
                 <label className="text-[10px] text-slate-400 font-medium uppercase tracking-wider">傾斜 (X軸)</label>
                 <span className="text-blue-400 font-mono text-xs">{((selectedShape.rotation[0] * 180) / Math.PI).toFixed(0)}°</span>
              </div>
              <input
                type="range"
                min={-Math.PI}
                max={Math.PI}
                step="0.1"
                value={selectedShape.rotation[0]}
                onChange={(e) => {
                    const newRot = [...selectedShape.rotation] as [number, number, number];
                    newRot[0] = parseFloat(e.target.value);
                    updateShape(selectedShape.id, { rotation: newRot });
                }}
                className="w-full h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-red-500"
              />
            </div>
        )}

        {/* Color Picker */}
        <div className="space-y-1.5 pt-1">
          <label className="text-[10px] text-slate-400 font-medium uppercase tracking-wider">材質顏色</label>
          <div className="grid grid-cols-5 gap-1.5">
            {PRESET_COLORS.map(color => (
              <button
                key={color}
                onClick={() => updateShape(selectedShape.id, { color })}
                className={`w-full aspect-square rounded border transition-transform hover:scale-110 ${selectedShape.color === color ? 'border-white ring-1 ring-blue-500/50' : 'border-transparent'}`}
                style={{ backgroundColor: color }}
              />
            ))}
            <div className="relative w-full aspect-square rounded overflow-hidden bg-gradient-to-br from-white to-black border border-slate-600 hover:scale-110 transition-transform">
                <input 
                    type="color" 
                    className="absolute inset-0 w-[150%] h-[150%] -top-1/4 -left-1/4 cursor-pointer opacity-0" 
                    value={selectedShape.color}
                    onChange={(e) => updateShape(selectedShape.id, { color: e.target.value })}
                />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PropertiesPanel;

import React from 'react';
import { useApp } from '../context/AppContext';
import { PRESET_COLORS } from '../constants';
import { Trash2, Copy, Maximize, Layers, ArrowUpFromLine, RefreshCw } from 'lucide-react';
import { IPoint } from '../types';

// Helper to determine local bounding box from points
const getRawDimensions = (points: IPoint[]) => {
  if (points.length === 0) return { width: 0, depth: 0 };
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
  points.forEach(p => {
    minX = Math.min(minX, p.x);
    maxX = Math.max(maxX, p.x);
    minZ = Math.min(minZ, p.z);
    maxZ = Math.max(maxZ, p.z);
  });
  return { 
    width: maxX - minX || 0.1, 
    depth: maxZ - minZ || 0.1 
  };
};

const PropertiesPanel: React.FC = () => {
  const { selectedIds, shapes, updateShape, updateShapes, removeSelected, copySelected, formatValue, unit } = useApp();

  if (selectedIds.length === 0) {
    return null;
  }

  // --- Multi Selection View ---
  if (selectedIds.length > 1) {
      return (
        <div className="absolute top-20 right-4 w-60 bg-slate-800/90 backdrop-blur-sm rounded-xl border border-slate-700 shadow-xl z-30 flex flex-col overflow-hidden">
            <div className="p-3 border-b border-slate-700 bg-slate-900/50 flex justify-between items-center sticky top-0 z-20">
                <h3 className="text-white font-semibold text-xs flex items-center gap-2">
                    <Layers size={14} className="text-blue-500"/>
                    <span>已選取 {selectedIds.length} 個物件</span>
                </h3>
                <div className="flex gap-1">
                    <button 
                        onClick={copySelected}
                        className="text-indigo-400 hover:text-indigo-300 p-1 hover:bg-indigo-500/10 rounded transition-colors"
                        title="複製選取物件"
                    >
                        <Copy size={14} />
                    </button>
                    <button 
                        onClick={removeSelected}
                        className="text-red-400 hover:text-red-300 p-1 hover:bg-red-500/10 rounded transition-colors"
                        title="刪除選取物件"
                    >
                        <Trash2 size={14} />
                    </button>
                </div>
            </div>
            <div className="p-3 space-y-4">
                 {/* Batch Color Picker */}
                <div className="space-y-1.5">
                    <label className="text-[10px] text-slate-400 font-medium uppercase tracking-wider">批次修改顏色</label>
                    <div className="grid grid-cols-4 gap-1.5">
                        {PRESET_COLORS.map(color => (
                        <button
                            key={color}
                            onClick={() => {
                                const updates = selectedIds.map(id => ({ id, changes: { color }}));
                                updateShapes(updates);
                            }}
                            className={`w-full aspect-square rounded-md border-2 border-transparent hover:scale-105 transition-transform`}
                            style={{ backgroundColor: color }}
                        />
                        ))}
                    </div>
                </div>
            </div>
        </div>
      );
  }

  // --- Single Selection View ---
  const selectedShape = shapes.find(s => s.id === selectedIds[0]);
  if (!selectedShape) return null;

  // Calculate current real-world dimensions
  const rawDims = getRawDimensions(selectedShape.points);
  const currentWidth = rawDims.width * selectedShape.scale[0];
  const currentDepth = rawDims.depth * selectedShape.scale[2];

  // Simple numeric updates (Standard center-based scaling for manual input)
  const handleDimensionChange = (newVal: number, type: 'width' | 'depth') => {
    if (isNaN(newVal) || newVal <= 0) return;
    const baseSize = type === 'width' ? rawDims.width : rawDims.depth;
    if (baseSize < 0.001) return;
    const newScaleVal = newVal / baseSize;

    const newScale = [...selectedShape.scale] as [number, number, number];
    if (type === 'width') newScale[0] = newScaleVal;
    if (type === 'depth') newScale[2] = newScaleVal;

    updateShape(selectedShape.id, { scale: newScale });
  };

  const getUnitVal = (val: number) => unit === 'cm' ? parseFloat((val * 100).toFixed(1)) : parseFloat(val.toFixed(3));
  const setUnitVal = (val: number) => unit === 'cm' ? val / 100 : val;

  const toDegrees = (rad: number) => Math.round((rad * 180) / Math.PI);
  const toRadians = (deg: number) => (deg * Math.PI) / 180;

  return (
    <div className="absolute top-20 right-4 w-60 bg-slate-800/90 backdrop-blur-sm rounded-xl border border-slate-700 shadow-xl z-30 flex flex-col overflow-hidden max-h-[calc(100vh-6rem)] overflow-y-auto">
      <div className="p-3 border-b border-slate-700 bg-slate-900/50 flex justify-between items-center sticky top-0 z-20">
        <h3 className="text-white font-semibold text-xs flex items-center gap-2">
          <span className={`w-1.5 h-4 rounded-full bg-blue-500`}/>
          屬性
        </h3>
        <div className="flex gap-1">
          <button 
            onClick={copySelected}
            className="text-indigo-400 hover:text-indigo-300 p-1 hover:bg-indigo-500/10 rounded transition-colors"
            title="複製物件"
          >
            <Copy size={14} />
          </button>
          <button 
            onClick={removeSelected}
            className="text-red-400 hover:text-red-300 p-1 hover:bg-red-500/10 rounded transition-colors"
            title="刪除物件"
          >
            <Trash2 size={14} />
          </button>
        </div>
      </div>

      <div className="p-3 space-y-4">

        {/* Name */}
        <div className="space-y-1.5">
            <label className="text-[10px] text-slate-400 font-medium uppercase tracking-wider">名稱</label>
            <input 
                type="text" 
                value={selectedShape.name} 
                onChange={(e) => updateShape(selectedShape.id, { name: e.target.value })}
                className="w-full bg-slate-900 border border-slate-600 rounded px-2 py-1 text-white text-xs focus:border-blue-500 focus:outline-none"
            />
        </div>

        {/* Text Content - Only for Text shapes */}
        {selectedShape.type === 'text' && (
             <div className="space-y-1.5 pt-2 border-t border-slate-700/50">
                <label className="text-[10px] text-slate-400 font-medium uppercase tracking-wider">文字內容</label>
                <textarea 
                    value={selectedShape.content || ''} 
                    onChange={(e) => updateShape(selectedShape.id, { content: e.target.value })}
                    className="w-full bg-slate-900 border border-slate-600 rounded px-2 py-1 text-white text-xs focus:border-blue-500 focus:outline-none resize-none h-16"
                />
                 <div className="flex justify-between items-center mt-2">
                     <label className="text-[10px] text-slate-400 font-medium uppercase tracking-wider">字體大小</label>
                     <input 
                        type="number" 
                        step={0.1}
                        value={selectedShape.fontSize || 0.5}
                        onChange={(e) => updateShape(selectedShape.id, { fontSize: parseFloat(e.target.value) })}
                        className="w-16 bg-slate-900 border border-slate-600 rounded px-1.5 py-0.5 text-white text-xs font-mono focus:border-blue-500 outline-none text-right"
                     />
                 </div>
            </div>
        )}

        {/* --- Dimensions Section --- */}
        {selectedShape.type !== 'text' && selectedShape.type !== 'line' && (
            <div className="space-y-2 pt-2 border-t border-slate-700/50">
            <div className="flex justify-between items-center mb-1">
                <label className="text-[10px] text-slate-400 font-medium uppercase tracking-wider flex items-center gap-1">
                    尺寸 <Maximize size={10}/>
                </label>
                <span className="text-[9px] text-slate-500">拖曳方塊縮放</span>
            </div>

            <div className="flex gap-2">
                <div className="flex-1 space-y-1.5">
                    <div className="flex items-center gap-1.5">
                        <div className="w-4 text-center text-red-400 font-bold font-mono text-[10px]">W</div>
                        <input 
                        type="number"
                        step={unit === 'm' ? 0.1 : 10}
                        value={getUnitVal(currentWidth)}
                        onChange={(e) => handleDimensionChange(setUnitVal(parseFloat(e.target.value)), 'width')}
                        className="flex-1 bg-slate-900 border border-slate-600 rounded px-1.5 py-0.5 text-white text-xs font-mono focus:border-red-500 outline-none"
                        />
                    </div>
                    <div className="flex items-center gap-1.5">
                        <div className="w-4 text-center text-blue-400 font-bold font-mono text-[10px]">D</div>
                        <input 
                        type="number"
                        step={unit === 'm' ? 0.1 : 10}
                        value={getUnitVal(currentDepth)}
                        onChange={(e) => handleDimensionChange(setUnitVal(parseFloat(e.target.value)), 'depth')}
                        className="flex-1 bg-slate-900 border border-slate-600 rounded px-1.5 py-0.5 text-white text-xs font-mono focus:border-blue-500 outline-none"
                        />
                    </div>
                </div>
            </div>
            </div>
        )}

        {/* Elevation (Y Position) */}
        <div className="space-y-2 pt-2 border-t border-slate-700/50">
          <div className="flex justify-between items-center">
             <label className="text-[10px] text-slate-400 font-medium uppercase tracking-wider flex items-center gap-1">
                <ArrowUpFromLine size={10}/> 離地高度
             </label>
             <div className="flex items-center gap-1">
                 <input 
                    type="number" 
                    step={unit === 'm' ? 0.1 : 10}
                    value={getUnitVal(selectedShape.position[1])}
                    onChange={(e) => {
                        const newY = setUnitVal(parseFloat(e.target.value));
                        const newPos = [...selectedShape.position];
                        newPos[1] = newY;
                        updateShape(selectedShape.id, { position: newPos as [number, number, number] });
                    }}
                    className="w-14 bg-slate-900 border border-slate-600 rounded px-1.5 py-0.5 text-white text-xs font-mono focus:border-green-500 outline-none text-right"
                 />
                 <span className="text-[9px] text-slate-500">{unit === 'cm' ? 'cm' : 'm'}</span>
             </div>
          </div>
          <input
            type="range"
            min="0"
            max="3"
            step="0.01"
            value={selectedShape.position[1]}
            onChange={(e) => {
                const newPos = [...selectedShape.position];
                newPos[1] = parseFloat(e.target.value);
                updateShape(selectedShape.id, { position: newPos as [number, number, number] });
            }}
            className="w-full h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-green-500"
          />
        </div>

        {/* Height Slider (Extrusion) - Not for Text */}
        {selectedShape.type !== 'text' && selectedShape.type !== 'line' && (
            <div className="space-y-2 pt-2 border-t border-slate-700/50">
            <div className="flex justify-between items-center">
                <label className="text-[10px] text-slate-400 font-medium uppercase tracking-wider">本體高度</label>
                <div className="flex items-center gap-1">
                    <input 
                        type="number" 
                        step={unit === 'm' ? 0.1 : 5}
                        value={getUnitVal(selectedShape.height)}
                        onChange={(e) => updateShape(selectedShape.id, { height: setUnitVal(parseFloat(e.target.value)) })}
                        className="w-14 bg-slate-900 border border-slate-600 rounded px-1.5 py-0.5 text-white text-xs font-mono focus:border-green-500 outline-none text-right"
                    />
                    <span className="text-[9px] text-slate-500">{unit === 'cm' ? 'cm' : 'm'}</span>
                </div>
            </div>
            <input
                type="range"
                min="0.05"
                max="5"
                step="0.05"
                value={selectedShape.height}
                onChange={(e) => updateShape(selectedShape.id, { height: parseFloat(e.target.value) })}
                className="w-full h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-slate-400"
            />
            </div>
        )}

        {/* --- Rotation Controls --- */}
        <div className="space-y-3 pt-2 border-t border-slate-700/50">
            <div className="flex items-center gap-1">
                <RefreshCw size={12} className="text-slate-400" />
                <label className="text-[10px] text-slate-400 font-medium uppercase tracking-wider">旋轉設定</label>
            </div>

            {/* Y Rotation (Standard Direction for all objects) */}
            <div className="space-y-1">
                <div className="flex justify-between items-center">
                    <label className="text-[10px] text-slate-500 font-medium">方向 (Y軸)</label>
                    <input
                        type="number"
                        value={toDegrees(selectedShape.rotation[1])}
                        onChange={(e) => {
                            const newRot = [...selectedShape.rotation] as [number, number, number];
                            newRot[1] = toRadians(parseFloat(e.target.value) || 0);
                            updateShape(selectedShape.id, { rotation: newRot });
                        }}
                        className="w-12 bg-slate-900 border border-slate-600 rounded px-1 py-0.5 text-white text-xs font-mono text-right outline-none focus:border-blue-500"
                    />
                </div>
                <input
                    type="range"
                    min="0"
                    max={Math.PI * 2}
                    step="0.05"
                    value={(selectedShape.rotation[1] + Math.PI * 2) % (Math.PI * 2)}
                    onChange={(e) => {
                        const newRot = [...selectedShape.rotation] as [number, number, number];
                        newRot[1] = parseFloat(e.target.value);
                        updateShape(selectedShape.id, { rotation: newRot });
                    }}
                    className="w-full h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
                />
            </div>

            {/* Extra Rotation Axes for Text (Allow 360 freedom) */}
            {selectedShape.type === 'text' && (
                <>
                    {/* X Rotation (Tilt) */}
                    <div className="space-y-1">
                        <div className="flex justify-between items-center">
                            <label className="text-[10px] text-slate-500 font-medium">傾斜 (X軸)</label>
                            <input
                                type="number"
                                value={toDegrees(selectedShape.rotation[0])}
                                onChange={(e) => {
                                    const newRot = [...selectedShape.rotation] as [number, number, number];
                                    newRot[0] = toRadians(parseFloat(e.target.value) || 0);
                                    updateShape(selectedShape.id, { rotation: newRot });
                                }}
                                className="w-12 bg-slate-900 border border-slate-600 rounded px-1 py-0.5 text-white text-xs font-mono text-right outline-none focus:border-red-500"
                            />
                        </div>
                        <input
                            type="range"
                            min={-Math.PI}
                            max={Math.PI}
                            step="0.05"
                            value={selectedShape.rotation[0]}
                            onChange={(e) => {
                                const newRot = [...selectedShape.rotation] as [number, number, number];
                                newRot[0] = parseFloat(e.target.value);
                                updateShape(selectedShape.id, { rotation: newRot });
                            }}
                            className="w-full h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-red-500"
                        />
                        <div className="flex justify-between text-[9px] text-slate-600 px-1">
                            <span>-180°</span>
                            <span className="cursor-pointer hover:text-red-400" onClick={() => {
                                const newRot = [...selectedShape.rotation] as [number, number, number];
                                newRot[0] = -Math.PI/2;
                                updateShape(selectedShape.id, { rotation: newRot });
                            }}>平躺</span>
                            <span className="cursor-pointer hover:text-red-400" onClick={() => {
                                const newRot = [...selectedShape.rotation] as [number, number, number];
                                newRot[0] = 0;
                                updateShape(selectedShape.id, { rotation: newRot });
                            }}>直立</span>
                            <span>180°</span>
                        </div>
                    </div>

                    {/* Z Rotation (Spin/Roll) */}
                    <div className="space-y-1">
                        <div className="flex justify-between items-center">
                            <label className="text-[10px] text-slate-500 font-medium">自轉 (Z軸)</label>
                            <input
                                type="number"
                                value={toDegrees(selectedShape.rotation[2] || 0)}
                                onChange={(e) => {
                                    const newRot = [...selectedShape.rotation] as [number, number, number];
                                    newRot[2] = toRadians(parseFloat(e.target.value) || 0);
                                    updateShape(selectedShape.id, { rotation: newRot });
                                }}
                                className="w-12 bg-slate-900 border border-slate-600 rounded px-1 py-0.5 text-white text-xs font-mono text-right outline-none focus:border-green-500"
                            />
                        </div>
                        <input
                            type="range"
                            min={-Math.PI}
                            max={Math.PI}
                            step="0.05"
                            value={selectedShape.rotation[2] || 0}
                            onChange={(e) => {
                                const newRot = [...selectedShape.rotation] as [number, number, number];
                                newRot[2] = parseFloat(e.target.value);
                                updateShape(selectedShape.id, { rotation: newRot });
                            }}
                            className="w-full h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-green-500"
                        />
                    </div>
                </>
            )}
        </div>

        {/* Color Picker */}
        <div className="space-y-1.5 pt-1">
          <label className="text-[10px] text-slate-400 font-medium uppercase tracking-wider">材質顏色</label>
          <div className="grid grid-cols-5 gap-1.5">
            {PRESET_COLORS.map(color => (
              <button
                key={color}
                onClick={() => updateShape(selectedShape.id, { color })}
                className={`w-full aspect-square rounded border transition-transform hover:scale-110 ${selectedShape.color === color ? 'border-white ring-1 ring-blue-500/50' : 'border-transparent'}`}
                style={{ backgroundColor: color }}
              />
            ))}
            <div className="relative w-full aspect-square rounded overflow-hidden bg-gradient-to-br from-white to-black border border-slate-600 hover:scale-110 transition-transform">
                <input 
                    type="color" 
                    className="absolute inset-0 w-[150%] h-[150%] -top-1/4 -left-1/4 cursor-pointer opacity-0" 
                    value={selectedShape.color}
                    onChange={(e) => updateShape(selectedShape.id, { color: e.target.value })}
                />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PropertiesPanel;

