        <div className="flex gap-1">
          <button 
            onClick={copySelected}
            className="text-indigo-400 hover:text-indigo-300 p-1.5 hover:bg-indigo-500/10 rounded transition-colors"
            title="複製物件"
          >
            <Copy size={16} />
          </button>
          <button 
            onClick={removeSelected}
            className="text-red-400 hover:text-red-300 p-1.5 hover:bg-red-500/10 rounded transition-colors"
            title="刪除物件"
          >
            <Trash2 size={16} />
          </button>
        </div>
      </div>

      <div className="p-4 space-y-5">

        {/* Name */}
        <div className="space-y-2">
            <label className="text-[11px] text-slate-400 font-bold uppercase tracking-wider">名稱</label>
            <input 
                type="text" 
                value={selectedShape.name} 
                onChange={(e) => updateShape(selectedShape.id, { name: e.target.value })}
                className="w-full bg-slate-900/80 border border-slate-600 rounded-lg px-3 py-1.5 text-white text-sm focus:border-blue-500 focus:outline-none transition-colors"
            />
        </div>

        {/* Text Content - Only for Text shapes */}
        {selectedShape.type === 'text' && (
             <div className="space-y-2 pt-2 border-t border-slate-700/50">
                <label className="text-[11px] text-slate-400 font-bold uppercase tracking-wider">文字內容</label>
                <textarea 
                    value={selectedShape.content || ''} 
                    onChange={(e) => updateShape(selectedShape.id, { content: e.target.value })}
                    className="w-full bg-slate-900/80 border border-slate-600 rounded-lg px-3 py-2 text-white text-sm focus:border-blue-500 focus:outline-none resize-none h-20"
                />
                 <div className="flex justify-between items-center mt-3">
                     <label className="text-[11px] text-slate-400 font-bold uppercase tracking-wider">字體大小</label>
                     <input 
                        type="number" 
                        step={0.1}
                        value={selectedShape.fontSize || 0.5}
