                        <input 
                        type="number"
                        step={unit === 'm' ? 0.1 : 10}
                        value={getUnitVal(currentWidth)}
                        onChange={(e) => handleDimensionChange(setUnitVal(parseFloat(e.target.value)), 'width')}
                        className="flex-1 bg-slate-900/80 border border-slate-600 rounded px-2 py-1 text-white text-sm font-mono focus:border-red-500 outline-none transition-colors"
