import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { Eye, EyeOff, Plus, Trash2, Layers, X, GripVertical, CheckCircle2, Circle } from 'lucide-react';

const LayerManager: React.FC = () => {
