import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { generateLayoutFromPrompt } from '../services/geminiService';
import { Sparkles, Loader2, AlertCircle } from 'lucide-react';

const AIAssistant: React.FC = () => {
  const { addAIShapes } = useApp();
  const [prompt, setPrompt] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isOpen, setIsOpen] = useState(false);

  const handleGenerate = async () => {
    if (!prompt.trim()) return;

    setLoading(true);
    setError(null);

    try {
      if (!process.env.API_KEY) {
        throw new Error("環境中未設定 API Key。");
      }
      const items = await generateLayoutFromPrompt(prompt);
      addAIShapes(items);
      setPrompt('');
      setIsOpen(false);
    } catch (err: any) {
      setError(err.message || "生成佈局失敗。");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="relative pointer-events-auto z-50">
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border shadow-sm transition-all duration-200 font-medium text-xs backdrop-blur-sm
          ${isOpen 
            ? 'bg-indigo-600 text-white border-indigo-500' 
            : 'bg-white/90 text-indigo-600 border-indigo-200 hover:bg-indigo-50'}`}
      >
        <Sparkles size={14} className={loading ? "animate-pulse" : ""} />
        {isOpen ? '關閉助手' : 'AI 助手'}
      </button>

      {isOpen && (
        <div className="absolute top-full left-0 mt-2 w-80 bg-white/95 backdrop-blur-md rounded-xl border border-indigo-100 shadow-2xl p-4 animate-in fade-in slide-in-from-top-2 origin-top-left z-50">
          <div className="flex items-center gap-2 mb-3 text-indigo-600 font-bold">
            <Sparkles size={18} />
            <h3>AI 佈局助手</h3>
          </div>

          <p className="text-slate-500 text-sm mb-3">
            請描述您想要的房間或佈局 (例如：「一間會議室，中間有一張大長桌和 8 把椅子，角落有盆栽」)。
          </p>

          <textarea
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            className="w-full bg-slate-50 border border-slate-200 rounded-lg p-3 text-slate-800 text-sm focus:border-indigo-500 focus:outline-none resize-none h-24 mb-3 focus:ring-2 focus:ring-indigo-500/20"
            placeholder="請輸入描述..."
