          {error && (
            <div className="flex items-center gap-2 text-red-500 text-xs mb-3 bg-red-50 p-2 rounded border border-red-100">
              <AlertCircle size={14} />
              {error}
            </div>
          )}

          <div className="flex justify-end gap-2">
            <button 
              onClick={() => setIsOpen(false)}
              className="px-3 py-1.5 text-xs text-slate-500 hover:text-slate-800 transition-colors"
            >
              取消
            </button>
            <button
              onClick={handleGenerate}
              disabled={loading || !prompt.trim()}
              className="flex items-center gap-2 px-4 py-1.5 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 text-white text-sm rounded-lg font-medium transition-colors shadow-sm"
            >
              {loading && <Loader2 size={14} className="animate-spin" />}
              {loading ? '思考中...' : '開始生成'}
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

