      <div className="flex flex-col gap-2 bg-white p-2 rounded-2xl border border-slate-200 shadow-[0_8px_30px_rgb(0,0,0,0.12)]">
        <div className="text-[10px] text-slate-400 font-bold uppercase tracking-widest px-1 py-2 text-center border-b border-slate-100 mb-1">
          工具箱
        </div>

        {standardTools.map((t) => (
          <React.Fragment key={t.type}>
            <button
              onClick={() => setTool(t.type)}
              className={`flex items-center justify-center w-12 h-12 rounded-xl transition-all duration-200 group relative
                ${tool === t.type 
                  ? 'bg-blue-50 text-white shadow-lg shadow-blue-500/30' 
                  : 'text-slate-500 hover:bg-slate-100 hover:text-slate-800'
                }`}
            >
              {t.icon}
              <span className="absolute left-full ml-4 px-3 py-1.5 bg-slate-800 text-white text-xs font-medium rounded-lg opacity-0 group-hover:opacity-100 whitespace-nowrap pointer-events-none transition-all z-20 shadow-xl translate-x-[-10px] group-hover:translate-x-0">
                {t.label}
              </span>
            </button>
          </React.Fragment>
        ))}

        {/* Combined Measure/Dimension Button */}
        <button
            onClick={handleMeasureClick}
            className={`flex items-center justify-center w-12 h-12 rounded-xl transition-all duration-200 group relative
              ${isMeasureActive 
                ? 'bg-blue-50 text-white shadow-lg shadow-blue-500/30' 
                : 'text-slate-500 hover:bg-slate-100 hover:text-slate-800'
              }`}
        >
            <MeasureIcon size={24} />
            <span className="absolute left-full ml-4 px-3 py-1.5 bg-slate-800 text-white text-xs font-medium rounded-lg opacity-0 group-hover:opacity-100 whitespace-nowrap pointer-events-none transition-all z-20 shadow-xl translate-x-[-10px] group-hover:translate-x-0">
              {measureLabel}
            </span>
        </button>

        {/* Clear Guides Button - Only shows when there are guide lines */}
        {guideLines.length > 0 && (
            <>
                <div className="h-px bg-slate-200 my-1 mx-2" />
                <button
                    onClick={clearGuideLines}
                    className="flex items-center justify-center w-12 h-12 rounded-xl text-purple-500 hover:bg-purple-50 hover:text-purple-600 transition-all duration-200 group relative"
                >
                    <Trash size={20} />
                    <span className="absolute left-full ml-4 px-3 py-1.5 bg-slate-800 text-white text-xs font-medium rounded-lg opacity-0 group-hover:opacity-100 whitespace-nowrap pointer-events-none transition-all z-20 shadow-xl">
                        刪除所有輔助線
                    </span>
                </button>
            </>
        )}

        {selectedIds.length > 1 && (
            <>
                <div className="h-px bg-slate-200 my-1 mx-2" />
                <button
                onClick={groupSelected}
                className="flex items-center justify-center w-12 h-12 rounded-xl text-slate-500 hover:bg-slate-100 hover:text-slate-800 transition-all duration-200 group relative"
                >
                <Group size={24} />
                <span className="absolute left-full ml-4 px-3 py-1.5 bg-slate-800 text-white text-xs font-medium rounded-lg opacity-0 group-hover:opacity-100 whitespace-nowrap pointer-events-none transition-all z-20 shadow-xl">
                    建立群組
